import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Generate initials from a name or email address.
 */
export function generateInitials(name?: string, email?: string): string {
  if (name && name.trim()) {
    const nameParts = name.trim().split(" ");
    if (
      nameParts.length >= 2 &&
      nameParts[0] &&
      nameParts[nameParts.length - 1] &&
      nameParts[0][0] &&
      nameParts[nameParts.length - 1]?.[0]
    ) {
      return (
        nameParts[0][0] + nameParts[nameParts.length - 1]![0]
      ).toUpperCase();
    }
    if (nameParts[0] && nameParts[0].length > 0 && nameParts[0][0]) {
      return nameParts[0][0].toUpperCase();
    }
  }
  if (email) {
    const emailParts = email.split("@");
    if (
      emailParts[0] &&
      emailParts[0].length >= 2 &&
      emailParts[0][0] &&
      emailParts[0][1]
    ) {
      return (emailParts[0][0] + emailParts[0][1]).toUpperCase();
    }
    if (emailParts[0] && emailParts[0].length > 0 && emailParts[0][0]) {
      return emailParts[0][0].toUpperCase();
    }
  }
  return "U";
}

"use client";

import { Slot } from "@radix-ui/react-slot";
import { forwardRef, type AnchorHTMLAttributes } from "react";
import { cn } from "../lib/utils";

export interface AnchorProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  variant?: "unstyled" | "text" | "muted" | "foreground";
  size?: "inherit" | "xs" | "sm";
  display?: "inline" | "inline-flex" | "block";
  underline?: boolean;
  asChild?: boolean;
  border?: "none" | "bottom";
  weight?: "normal" | "medium";
}

/** Router-agnostic native anchor owned by the design system. */
export const Anchor = forwardRef<HTMLAnchorElement, AnchorProps>(function Anchor(
  { variant = "unstyled", size = "inherit", display = "inline", underline = false, asChild = false, border = "none", weight = "normal", className, ...props },
  ref,
) {
  const Component = asChild ? Slot : "a";
  return (
    <Component
      ref={ref}
      className={cn(
        variant === "text" && "font-medium text-primary underline-offset-4 hover:underline",
        variant === "muted" && "text-muted-foreground underline underline-offset-2 hover:text-foreground",
        variant === "foreground" && "text-foreground underline-offset-2 hover:underline",
        size === "xs" && "text-xs",
        size === "sm" && "text-sm",
        display === "inline-flex" && "inline-flex items-center gap-1",
        display === "block" && "block",
        border === "bottom" && "border-b last:border-b-0",
        weight === "medium" && "font-medium",
        underline && "underline",
        className,
      )}
      {...props}
    />
  );
});

"use client";

import * as AspectRatioPrimitive from "@radix-ui/react-aspect-ratio"

const AspectRatio = AspectRatioPrimitive.Root

export { AspectRatio }

"use client";

import * as AvatarPrimitive from "@radix-ui/react-avatar";

import type { ComponentPropsWithoutRef, ElementRef } from "react";

import { cn } from "../lib/utils";
import { forwardRef } from "react";

export interface AvatarProps extends ComponentPropsWithoutRef<typeof AvatarPrimitive.Root> {
  size?: "xs" | "sm" | "md" | "lg" | "xl" | "2xl";
  shape?: "circle" | "square";
  border?: boolean;
  surface?: "default" | "muted";
}

const Avatar = forwardRef<
  ElementRef<typeof AvatarPrimitive.Root>,
  AvatarProps
>(({ className, size = "md", shape = "circle", border = false, surface = "default", ...props }, ref) => (
  <AvatarPrimitive.Root
    ref={ref}
    className={cn(
      "relative flex shrink-0 overflow-hidden",
      size === "xs" && "size-7",
      size === "sm" && "size-9",
      size === "md" && "size-10",
      size === "lg" && "size-11",
      size === "xl" && "size-12",
      size === "2xl" && "size-16",
      shape === "circle" ? "rounded-full" : "rounded-md",
      border && "border",
      surface === "muted" && "bg-muted",
      className
    )}
    {...props}
  />
));
Avatar.displayName = AvatarPrimitive.Root.displayName;

export interface AvatarImageProps extends ComponentPropsWithoutRef<typeof AvatarPrimitive.Image> {
  fit?: "cover" | "contain";
}

const AvatarImage = forwardRef<
  ElementRef<typeof AvatarPrimitive.Image>,
  AvatarImageProps
>(({ className, fit = "cover", ...props }, ref) => (
  // object-cover is critical — without it the underlying <img>
  // defaults to object-fit: fill and stretches portrait/landscape
  // photos to fit the square Avatar container. Crop-to-square is
  // the standard avatar behaviour and what every consumer expects.
  <AvatarPrimitive.Image
    ref={ref}
    className={cn("aspect-square h-full w-full", fit === "cover" ? "object-cover" : "object-contain", className)}
    {...props}
  />
));
AvatarImage.displayName = AvatarPrimitive.Image.displayName;

export interface AvatarFallbackProps extends ComponentPropsWithoutRef<typeof AvatarPrimitive.Fallback> {
  shape?: "circle" | "square";
  textSize?: "default" | "micro";
}

const AvatarFallback = forwardRef<
  ElementRef<typeof AvatarPrimitive.Fallback>,
  AvatarFallbackProps
>(({ className, shape = "circle", textSize = "default", ...props }, ref) => (
  <AvatarPrimitive.Fallback
    ref={ref}
    className={cn(
      "flex h-full w-full items-center justify-center bg-muted",
      shape === "circle" ? "rounded-full" : "rounded-md",
      textSize === "micro" && "text-[10px]",
      className
    )}
    {...props}
  />
));
AvatarFallback.displayName = AvatarPrimitive.Fallback.displayName;

export { Avatar, AvatarFallback, AvatarImage };

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import type { ElementType } from "react";

import { cn } from "../lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-full border border-border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2 dark:border-border dark:focus:ring-ring",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-muted text-muted-foreground hover:bg-muted/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
        outline: "text-foreground",
        // Semantic variants for status badges
        success:
          "border-transparent bg-green-100 text-green-800 dark:bg-green-900/20 dark:text-green-400 hover:bg-green-100/80",
        warning:
          "border-transparent bg-yellow-100 text-yellow-800 dark:bg-yellow-900/20 dark:text-yellow-400 hover:bg-yellow-100/80",
        error:
          "border-transparent bg-red-100 text-red-800 dark:bg-red-900/20 dark:text-red-400 hover:bg-red-100/80",
        info:
          "border-transparent bg-blue-100 text-blue-800 dark:bg-blue-900/20 dark:text-blue-400 hover:bg-blue-100/80",
        neutral:
          "border-transparent bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300 hover:bg-gray-100/80",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {
  weight?: "normal" | "semibold" | "bold";
  gap?: "none" | "xs";
  size?: "default" | "compact" | "micro" | "micro-compact" | "tiny" | "counter" | "tile" | "rule";
  padding?: "default" | "roomy";
  shrink?: boolean;
  interactive?: boolean;
  marginStart?: "none" | "md";
  transform?: "none" | "uppercase";
  shape?: "pill" | "rounded";
  marginTop?: "none" | "tight";
  as?: ElementType;
  font?: "sans" | "mono";
  titleCase?: "preserve" | "capitalize";
}

// Export the variant type for use in other components
export type BadgeVariant = NonNullable<BadgeProps["variant"]>;

function Badge({ className, variant, weight = "semibold", gap = "xs", size = "default", padding = "default", shrink = false, interactive = false, marginStart = "none", transform = "none", shape = "pill", marginTop = "none", font = "sans", titleCase = "preserve", as, ...props }: BadgeProps) {
  const Component = (as ?? "div") as ElementType;
  return (
    <Component data-slot="badge" data-variant={variant ?? "default"} data-size={size} data-padding={padding} data-shape={shape} className={cn(
      badgeVariants({ variant }),
      weight === "normal" && "font-normal",
      weight === "bold" && "font-bold",
      gap === "xs" && "gap-1",
      size === "compact" && "px-1.5 py-0.5 text-[11px] leading-none",
      size === "micro" && "text-[10px]",
      size === "micro-compact" && "px-1.5 py-0 text-[10px] leading-none",
      size === "tiny" && "h-3.5 px-1 py-0 text-[9px]",
      size === "counter" && "h-5 min-w-5 justify-center px-1.5",
      size === "tile" && "h-8 w-8 justify-center p-0 text-sm",
      size === "rule" && "px-3 py-1.5 text-sm",
      padding === "roomy" && "px-3 py-1",
      shrink && "shrink-0",
      interactive && "cursor-pointer hover:bg-muted",
      marginStart === "md" && "ml-2",
      transform === "uppercase" && "uppercase tracking-wide",
      shape === "rounded" && "rounded-md",
      marginTop === "tight" && "mt-0.5",
      font === "mono" && "font-mono",
      titleCase === "capitalize" && "capitalize",
      className,
    )} {...props} />
  );
}

export { Badge, badgeVariants };

"use client";

