export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = forwardRef<HTMLButtonElement, ButtonProps>(
({ className, variant, size, width, align, shrink, shape, ring, grow, minWidth, textAlign, marginTop, marginStart, reveal, interaction, position, transform, marginEnd, gap, numeric, asChild = false, ...props }, ref) => {
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      data-slot="button"
      data-variant={variant ?? "default"}
      data-size={size ?? "default"}
      data-shape={shape ?? "default"}
      className={cn(buttonVariants({ variant, size, width, align, shrink, shape, ring, grow, minWidth, textAlign, marginTop, marginStart, reveal, interaction, position, transform, marginEnd, gap, numeric, className }))}
